# Temporal-style saga orchestration
@workflow.defn
class OrderSaga:
    @workflow.run
    async def run(self, order: OrderInput) -> str:
        # T1: reserve inventory
        item_id = await workflow.execute_activity(
            reserve_inventory, order.sku, schedule_to_close_timeout=timedelta(seconds=10)
        )
        try:
            # T2: charge payment
            charge_id = await workflow.execute_activity(
                charge_payment, order.amount,
                schedule_to_close_timeout=timedelta(seconds=10)
            )
        except ActivityError:
            # C1: compensate — release inventory
            await workflow.execute_activity(release_inventory, item_id)
            raise
        return charge_id

-- Create a logical replication slot for Debezium
SELECT pg_create_logical_replication_slot(
    'debezium_slot', 'pgoutput'
);

-- Monitor slot lag (alert if lag_bytes > 1 GB)
SELECT slot_name,
       active,
       pg_wal_lsn_diff(
           pg_current_wal_lsn(),
           confirmed_flush_lsn
       ) AS lag_bytes
FROM pg_replication_slots
ORDER BY lag_bytes DESC;

-- Drop an unused slot (prevent disk exhaustion)
SELECT pg_drop_replication_slot('debezium_slot');

// LMDB: open environment and perform a transaction
#include <lmdb.h>

MDB_env *env;
mdb_env_create(&env);
mdb_env_set_mapsize(env, 1UL * 1024 * 1024 * 1024); // 1 GiB max
mdb_env_open(env, "/data/lmdb", 0, 0664);

MDB_txn *txn;
MDB_dbi dbi;
mdb_txn_begin(env, NULL, 0, &txn);  // write transaction
mdb_dbi_open(txn, NULL, 0, &dbi);

MDB_val key = {.mv_size=3, .mv_data="foo"};
MDB_val val = {.mv_size=3, .mv_data="bar"};
mdb_put(txn, dbi, &key, &val, 0);
mdb_txn_commit(txn);  // atomic CoW root pointer swap

// io_uring: batch 64 reads in one syscall
#include <liburing.h>

struct io_uring ring;
// SQPOLL: kernel thread polls SQ — zero syscall for submissions
io_uring_queue_init_params(64, &ring,
    &(struct io_uring_params){ .flags = IORING_SETUP_SQPOLL });

for (int i = 0; i < 64; i++) {
    struct io_uring_sqe *sqe = io_uring_get_sqe(&ring);
    io_uring_prep_read(sqe, fd, buf[i], PAGE_SIZE, offsets[i]);
    io_uring_sqe_set_data(sqe, &ctx[i]);
}
io_uring_submit(&ring);  // single syscall submits all 64

// Harvest completions (no syscall in SQPOLL mode)
struct io_uring_cqe *cqe;
unsigned head, count = 0;
io_uring_for_each_cqe(&ring, head, cqe) { count++; }
io_uring_cq_advance(&ring, count);
